// Background tabs pause requestAnimationFrame, but an authorized WebTransport
// session still needs a neutral liveness signal to avoid consuming a ghost slot.
// No gameplay action or movement may be generated by this packet.
export function neutralBackgroundInput(tick) {
  return {
    tick: tick >>> 0,
    moveX: 0, moveY: 0, facing: 0,
    attack: false, heavyAttack: false, dodge: false, block: false,
    kick: false, run: false, jump: false, dash: false,
  };
}
